#!/usr/bin/env bash
set -euo pipefail

RUNTIME_ENV_FILE="${RUNTIME_ENV_FILE:-/opt/vatranscribe/secrets/.env.runtime}"
SECRETS_DIR="$(dirname "${RUNTIME_ENV_FILE}")"

umask 077
mkdir -p "${SECRETS_DIR}"

tmp_file="$(mktemp "${SECRETS_DIR}/.env.runtime.XXXXXX")"
trap 'rm -f "${tmp_file}"' EXIT

write_var() {
  local name="$1"
  local value="${!name-}"
  if [[ -n "${value}" ]]; then
    printf '%s=%q\n' "${name}" "${value}" >> "${tmp_file}"
  fi
}

# Provider-neutral renderer: inject variables from the current process environment.
# Use GitHub Environments, Yandex Lockbox, Doppler, HashiCorp Vault, 1Password CLI
# or another tool to populate this process environment before running this script.
vars=(
  APP_NAME APP_ENV DEBUG EXPOSE_API_DOCS API_HOST API_PORT API_PREFIX
  SECRET_MANAGER_STRATEGY RUNTIME_ENV_FILE PRODUCTION_SECRETS_VALIDATION_REQUIRED SECRET_ROTATION_POLICY_VERSION
  PUBLIC_MARKETING_ORIGIN PUBLIC_APP_ORIGIN PUBLIC_API_ORIGIN PUBLIC_ADMIN_ORIGIN CORS_ORIGINS
  ROOT_DOMAIN MARKETING_DOMAIN APP_DOMAIN API_DOMAIN ADMIN_DOMAIN PRODUCTION_HOST_PUBLIC_IP DNS_PROVIDER CDN_PROVIDER CDN_API_ENABLED CDN_MARKETING_STATIC_ENABLED CDN_APP_STATIC_ENABLED CDN_HTML_CACHE_POLICY CDN_ASSET_CACHE_SECONDS CERTBOT_EMAIL CERTBOT_DOMAINS CERTBOT_PRIMARY_DOMAIN CERTBOT_WEBROOT CERTBOT_STAGING CERTBOT_RSA_KEY_SIZE CERTBOT_RENEW_DEPLOY_HOOK_RELOAD HSTS_PRELOAD_ENABLED CHECK_DOMAIN_READINESS
  PYTHONPATH DATABASE_URL POSTGRES_PASSWORD REDIS_URL CELERY_BROKER_URL CELERY_RESULT_BACKEND
  SECRET_KEY JWT_ALGORITHM ACCESS_TOKEN_EXPIRE_MINUTES REFRESH_TOKEN_EXPIRE_DAYS
  COOKIE_SECURE COOKIE_HTTPONLY COOKIE_SAMESITE COOKIE_DOMAIN REFRESH_COOKIE_NAME CSRF_COOKIE_NAME CSRF_HEADER_NAME
  STORAGE_ROOT UPLOADS_DIR DOWNLOADS_DIR DOWNLOADS_AUDIO_DIR DOWNLOADS_VIDEO_DIR TRANSCRIPTS_TXT_DIR TRANSCRIPTS_SRT_DIR TRANSCRIPTS_VTT_DIR TRANSCRIPTS_JSON_DIR TEMP_DIR LOGS_DIR COOKIES_DIR
  FFMPEG_PATH FFPROBE_PATH YT_DLP_PATH YT_DLP_COOKIES_FILE YOUTUBE_COOKIES_ENCRYPTION_KEY YOUTUBE_COOKIES_MAX_BYTES YOUTUBE_COOKIES_TEMP_DIR YT_DLP_PROXY_URL YT_DLP_YOUTUBE_PLAYER_CLIENT YT_DLP_YOUTUBE_PO_TOKEN
  VITE_API_BASE_URL PUBLIC_VATRANSCRIBE_APP_URL PUBLIC_VATRANSCRIBE_MARKETING_URL WEB_HTTP_PORT WEB_HTTPS_PORT VITE_BASE_PATH
  NGINX_SERVER_NAME NGINX_SSL_CERTIFICATE NGINX_SSL_CERTIFICATE_KEY NGINX_HSTS_MAX_AGE NGINX_GENERAL_API_RATE NGINX_AUTH_RATE NGINX_AUTH_STRICT_RATE NGINX_UPLOAD_RATE NGINX_DOWNLOAD_RATE NGINX_GLOBAL_BODY_LIMIT NGINX_AUTH_BODY_LIMIT NGINX_ANALYZE_BODY_LIMIT NGINX_UPLOAD_BODY_LIMIT
  RATE_LIMIT_BACKEND RATE_LIMIT_REDIS_URL RATE_LIMIT_FAIL_OPEN TRUSTED_PROXY_CIDRS RATE_LIMIT_GENERAL_API_PER_MINUTE RATE_LIMIT_AUTH_PER_MINUTE RATE_LIMIT_AUTH_STRICT_PER_MINUTE RATE_LIMIT_UPLOAD_PER_MINUTE RATE_LIMIT_DOWNLOAD_PER_MINUTE RATE_LIMIT_ANALYZE_PER_MINUTE
  ADMIN_2FA_REQUIRED ADMIN_2FA_ISSUER ADMIN_2FA_RECOVERY_CODE_COUNT ADMIN_2FA_RECOVERY_CODE_BYTES ADMIN_2FA_TOTP_WINDOW
  MAX_UPLOAD_BYTES UPLOAD_STREAM_CHUNK_BYTES MAX_EXTERNAL_DOWNLOAD_BYTES MAX_EXPORT_ARTIFACT_BYTES MAX_MEDIA_DOWNLOAD_BYTES TEMP_FILE_RETENTION_HOURS FAILED_JOB_FILE_RETENTION_DAYS EXPORT_ARTIFACT_RETENTION_DAYS MEDIA_ASSET_RETENTION_DAYS TRANSCRIPT_RETENTION_DAYS CLEANUP_BATCH_SIZE
  MONITORING_REQUIRED MONITORING_RELEASE_CHECKLIST_ACK UPTIME_PROVIDER UPTIME_ALERT_CHANNELS UPTIME_CHECKS_BASE_URL APM_PROVIDER SENTRY_REQUIRED SENTRY_DSN SENTRY_ENVIRONMENT SENTRY_TRACES_SAMPLE_RATE SENTRY_PROFILES_SAMPLE_RATE SENTRY_WORKER_ENABLED VITE_SENTRY_DSN VITE_SENTRY_ENVIRONMENT VITE_SENTRY_RELEASE VITE_SENTRY_TRACES_SAMPLE_RATE CENTRAL_LOGGING_REQUIRED CENTRAL_LOGGING_PROVIDER LOG_LEVEL LOG_JSON RELEASE_VERSION DOCKER_LOG_MAX_SIZE DOCKER_LOG_MAX_FILE LOG_RETENTION_DAYS LOKI_RETENTION_DAYS NGINX_ACCESS_LOG_RETENTION_DAYS NGINX_ERROR_LOG_RETENTION_DAYS REQUEST_ID_HEADER
  BACKUP_DIR BACKUP_RETENTION_DAILY BACKUP_RETENTION_WEEKLY BACKUP_RETENTION_MONTHLY AGE_RECIPIENT BACKUP_ENCRYPTION_RECIPIENT AGE_IDENTITY_FILE BACKUP_REMOTE BACKUP_REMOTE_PATH S3_REMOTE S3_BACKUP_PATH BACKUP_RPO_HOURS BACKUP_RTO_HOURS BACKUP_REQUIRE_ENCRYPTION BACKUP_VERIFY_AFTER_CREATE BACKUP_MANIFEST_VERSION RESTORE_DRILL_DATABASE RESTORE_DRILL_KEEP_DB RESTORE_DRILL_FREQUENCY RESTORE_DRILL_REPORT_DIR CRITICAL_RESTORE_TABLES BACKUP_RETENTION_PRUNE_REMOTE SMOKE_BASE_URL SMOKE_TIMEOUT_SECONDS
  SMTP_HOST SMTP_PORT SMTP_USERNAME SMTP_PASSWORD PAYMENT_PROVIDER PAYMENT_WEBHOOK_SECRET PAYMENT_API_KEY PAYMENT_WEBHOOK_SIGNATURE_HEADER BILLING_FAKE_UPGRADE_ENABLED BILLING_PAID_PLANS_ENABLED
  ANALYTICS_PROVIDER YANDEX_METRIKA_ID GA4_MEASUREMENT_ID POSTHOG_API_KEY POSTHOG_HOST COOKIE_CONSENT_REQUIRED COOKIE_CONSENT_VERSION CORE_WEB_VITALS_ENABLED CORE_WEB_VITALS_REPORT_MODE CORE_WEB_VITALS_LCP_TARGET_MS CORE_WEB_VITALS_INP_TARGET_MS CORE_WEB_VITALS_CLS_TARGET VITE_ANALYTICS_PROVIDER VITE_YANDEX_METRIKA_ID VITE_GA4_MEASUREMENT_ID VITE_POSTHOG_API_KEY VITE_POSTHOG_HOST VITE_COOKIE_CONSENT_REQUIRED VITE_COOKIE_CONSENT_VERSION VITE_CORE_WEB_VITALS_ENABLED VITE_CORE_WEB_VITALS_REPORT_MODE VITE_CORE_WEB_VITALS_LCP_TARGET_MS VITE_CORE_WEB_VITALS_INP_TARGET_MS VITE_CORE_WEB_VITALS_CLS_TARGET PUBLIC_ANALYTICS_PROVIDER PUBLIC_YANDEX_METRIKA_ID PUBLIC_GA4_MEASUREMENT_ID PUBLIC_POSTHOG_API_KEY PUBLIC_POSTHOG_HOST PUBLIC_COOKIE_CONSENT_REQUIRED PUBLIC_COOKIE_CONSENT_VERSION PUBLIC_CORE_WEB_VITALS_ENABLED PUBLIC_CORE_WEB_VITALS_REPORT_MODE PUBLIC_CORE_WEB_VITALS_LCP_TARGET_MS PUBLIC_CORE_WEB_VITALS_INP_TARGET_MS PUBLIC_CORE_WEB_VITALS_CLS_TARGET
  LEGAL_DOCUMENT_VERSION LEGAL_OPERATOR_TYPE LEGAL_OPERATOR_NAME LEGAL_OPERATOR_INN LEGAL_OPERATOR_OGRN LEGAL_OPERATOR_ADDRESS LEGAL_CONTACT_EMAIL PRIVACY_CONTACT_EMAIL SUPPORT_EMAIL LEGAL_PRODUCTION_DOMAINS LEGAL_TARGET_USERS LEGAL_MAIN_DB_COUNTRY LEGAL_BACKUP_COUNTRY LEGAL_HOSTING_PROVIDER LEGAL_CDN_PROVIDER LEGAL_ANALYTICS_PROVIDER LEGAL_APM_PROVIDER LEGAL_PAYMENT_PROVIDER LEGAL_EMAIL_PROVIDER LEGAL_YOUTUBE_COOKIES_UPLOAD_ENABLED LEGAL_ANALYTICS_COOKIES_ENABLED LEGAL_MARKETING_PIXELS_ENABLED LEGAL_CRM_AD_PIXELS_ENABLED LEGAL_AUDIT_LOGS_RETENTION_DAYS LEGAL_ACCOUNT_DELETION_GRACE_DAYS LEGAL_BACKUP_RETENTION_POLICY LEGAL_BILLING_RECORDS_RETENTION LEGAL_152FZ_RUSSIAN_PD LEGAL_152FZ_RKN_NOTIFICATION_STATUS LEGAL_152FZ_PD_LOCALIZATION_STATUS
)

for var in "${vars[@]}"; do
  write_var "$var"
done

install -m 600 "${tmp_file}" "${RUNTIME_ENV_FILE}"
trap - EXIT
rm -f "${tmp_file}"

echo "[OK] Runtime env rendered: ${RUNTIME_ENV_FILE}"
